using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData no longer accepts mutable values
        // like DateTime.UtcNow. Use a fixed seed value instead.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF Core 9 breaking changes ---

class CosmosAppDbContext : DbContext
{
    public DbSet<CosmosOrder> Orders => Set<CosmosOrder>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "OrdersDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<CosmosOrder>(b =>
        {
            b.ToContainer("Orders");
            b.HasPartitionKey(o => o.PartitionKey);

            // EF Core 9 breaking change: The Cosmos provider now uses
            // "$type" instead of "Discriminator" for the discriminator property.
            // For existing documents that already store "Discriminator", you must
            // explicitly configure backward-compatible mapping:
            b.HasDiscriminator<string>("Discriminator");
        });
    }
}

class CosmosOrder
{
    public string Id { get; set; } = default!;
    public string PartitionKey { get; set; } = default!;
    public DateTime CreatedAt { get; set; }
}

// --- Cosmos DB query service demonstrating sync → async migration ---

class CosmosQueryService
{
    // EF Core 9 breaking change: Synchronous I/O on Cosmos DB is no longer
    // supported (throws InvalidOperationException). All queries must be async.
    public async Task<List<CosmosOrder>> GetOrdersAsync(CosmosAppDbContext db)
    {
        // Before (EF Core 8): db.Orders.ToList()  — no longer works in EF Core 9
        // After  (EF Core 9): must use async
        return await db.Orders.ToListAsync();
    }

    public async Task<CosmosOrder?> FindOrderAsync(CosmosAppDbContext db, string id)
    {
        // Before (EF Core 8): db.Orders.FirstOrDefault(...)
        // After  (EF Core 9): must use async
        return await db.Orders.FirstOrDefaultAsync(o => o.Id == id);
    }
}

